/** PROCEDURE DIVISION USING WKS-USER, WKS-ARCHIVO, WKS-PACK-ORIGEN, WKS-PACK-DESTINO. */
public record SolicitudTransferencia(String usercode,     // X(04)
                                     String archivo,      // X(80) título completo
                                     String packOrigen,   // X(17)
                                     String packDestino)  // X(17)
{}

@MessagingGateway(defaultRequestChannel = "transferencias.entrada")
public interface TransferenciaGateway {
    /** Reemplaza el CALL a P102: los pasos que copiaban archivos publican la solicitud. */
    ResultadoTransferencia transfiere(SolicitudTransferencia solicitud);
}

@Bean
IntegrationFlow transferencias(RuteoEquipos ruteo, XferAdapter xfer) {
    return IntegrationFlow.from("transferencias.entrada")
            .<SolicitudTransferencia, ComandoXfer>transform(ruteo::resuelve)   // 000200-DETERMINA-NODOS
            .handle(xfer, "envia")                                              // 000300-ENVIA-ARCHIVO
            .get();
}

/** WKS-TITULO-ARCH-CAP: 192 posiciones; se entrega a XFER con longitud 193. */
public record ComandoXfer(String usercodeOrigen, String archivo, String usercodeDestino,
                          String archivoDestino, String packOrigen, String nodoOrigen,
                          String packDestino, String nodoDestino) {

    public String texto() {
        return "ADD " + fijo("(" + usercodeOrigen + ")", 6) + fijo(archivo, 55)
             + " AS (" + fijo(usercodeDestino, 4) + ")" + fijo(archivoDestino, 55)
             + " FROM " + fijo(packOrigen, 16) + "," + fijo(nodoOrigen, 9)
             + " TO " + fijo(packDestino, 16) + "," + fijo(nodoDestino, 9);
    }

    /** Igual que un MOVE alfanumérico: trunca a la derecha y rellena con espacios. */
    private static String fijo(String s, int n) {
        String v = (s == null) ? "" : s;
        if (v.length() > n) {
            throw new TituloTruncadoException(v, n);    // el COBOL truncaría en silencio
        }
        return String.format("%-" + n + "s", v);
    }
}

@Component
@RequiredArgsConstructor
public class EquipoActual {

    private final SoporteComsClient soporteComs;   // CALL "CSIID OF SOPORTECOMS" USING WKS-HOST

    /** WKS-HOST: CSI 9(02), host X(10) con punto final, nombre de CSI, línea o batch. */
    @Cacheable("equipo-actual")
    public Equipo identifica() {
        var h = soporteComs.csiId();
        return new Equipo(h.numCsi(), h.nombreHost().strip(), h.nombreCsi(), h.lineaBatch());
    }
}

public record Equipo(int csi, String host, String nombreCsi, String lineaBatch) {}

